head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/jquery-1.11.0.min.js");
scwin.vScrenID = "ULDSTF05241.xml";
scwin.pMenuID = $c.cm.InfoMenuID();
scwin.fn_GetPar, scwin.fn_SetPar;
// mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조. 
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.cm.InfoMenuID());
scwin.vBzProcsNo = "";
scwin.vListEligtyTpCd = "R";
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.trsIdx; // insert, update 구분
scwin.pMngId = js_id; //로그인 ID
scwin.selRow = "";
scwin.fileType;
scwin.market = js_market;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_searchCode = function() {
    /*
    02549-상장폐지 실질심사 사유코드(10: 회생절차개시신청(삭제)  화면에서만 안보여달라고 함)
    03576 - 상장폐지실질심사기타코드 
    */
    var arrCid = [{
        cid: "DELIST_REAL_INVSTG_RSN_CD",
        cnm: "cmb_DELIST_REAL_INVSTG_RSN_CD"
    }, {
        cid: "DELIST_REAL_INVSTG_MISC_CD",
        cnm: "cmb_DELIST_REAL_INVSTG_MISC_CD"
    }, {
        cid: "LIST_ELIGTY_DELIB_RSLT_CD",
        cnm: "cmb_LIST_ELIGTY_DELIB_RSLT_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='DELIST_REAL_INVSTG_RSN_CD','DELIST_REAL_INVSTG_MISC_CD','LIST_ELIGTY_DELIB_RSLT_CD','REAL_INVSTG_ABOL_LAWST_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    objCod = document.getElementById(arrCid[1].cnm);
    if (objCod == null) {
        $c.win.alert(arrCid[1].cnm);
    }
    strCbd = "";
    for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
        if (dts_Cod.getCellData(j, "CD_ENG_NM") == "DELIST_REAL_INVSTG_MISC_CD") {
            // 상장폐지실질심사기타코드
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[1].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT").replace(/,/g, "','");
            }
        }
    }
    objCod.CBData = strCbd;
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISUR_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_COM_NM.getValue(); // 발행기관명
    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
        txb_COM_NM.setValue(arrPar[0].COM_NM);
        scwin.fr_SecuGrpId = arrPar[0].SECUGRP_ID;
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = arrPar[0].SPOT_ISU_TRD_MKT_TP_CD;
        scwin.fn_initItem();
        scwin.fn_list_sync();
        buttonSet.setInsertStatus();
    }
};
scwin.fn_initItem = function() {
    buttonSet.setInsertStatus();
    dts_Mst.removeAll();
    dts_Mst.insertRow();
    dts_Mst.setCellData(1, "LIST_ELIGTY_TP_CD", scwin.vListEligtyTpCd);
    scwin.vBzProcsNo = ""; //초기화 

};


/**
 *	상장적격성 실질심사 내역
 */
scwin.fn_list_sync = function() {
    var url = "/RealInvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=realInvstgList&inputMessageId=REALINVSTG_DETAIL_LIST_NEW" + "&ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD) + "&LIST_ELIGTY_TP_CD=" + scwin.vListEligtyTpCd;
    dts_List.DataID = encodeURI(url);
    dts_List.Reset();
};
scwin.fn_afterFile = function() {
    scwin.fn_list_allDtl_sync("01", dts_Dtl1, dts_List.getRowPosition());
    scwin.fn_list_allDtl_sync("02", dts_Dtl2, dts_List.getRowPosition());
    scwin.fn_list_allDtl_sync("03", dts_Dtl3, dts_List.getRowPosition());
    scwin.fn_list_allDtl_sync("04", dts_Dtl4, dts_List.getRowPosition());
    scwin.fn_list_allDtl_sync("08", dts_Dtl5, dts_List.getRowPosition());
};


/**
 *	실질심사 결과 등 그리드 조회
 */
scwin.fn_list_allDtl_sync = function(procsCd, dataSet, row) {
    if (typeof row != "undefined") {
        scwin.vBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
    }
    var url = "/RealInvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=realInvstgDtlDetail&inputMessageId=REALINVSTG_DTLDETAIL_LIST" + "&LIST_ELIGTY_PROCS_CD=" + procsCd + "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dataSet.DataID = encodeURI(url);
    dataSet.Reset();
};


/**
 *	실질심사 사유 및 사유발생일 세부내역
 */
scwin.fn_OpenDetail = function(row) {
    scwin.vBzProcsNo = dts_List.getCellData(dts_List.getRowPosition(), "BZ_PROCS_NO");
    var url = "/RealInvstg.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=realInvstgDetail&inputMessageId=REALINVSTG_DETAIL_LIST_NEW" + "&BZ_PROCS_NO=" + scwin.vBzProcsNo + "&LIST_ELIGTY_TP_CD=" + scwin.vListEligtyTpCd;
    dts_Mst.DataID = encodeURI(url);
    dts_Mst.reset();
};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(txb_ISUR_CD) == "") {
        $c.win.alert("[회사]를 선택하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(rdo_ClmDtlWebDpYn) == "") {
        $c.win.alert("[웹반영여부]을 입력하세요.");
        rdo_ClmDtlWebDpYn.focus();
        return false;
    }
    if (med_ClmDtlWebDpDd.getValue() == "") {
        $c.win.alert("[웹반영일]을 입력하세요.");
        med_ClmDtlWebDpDd.focus();
        return false;
    } else {
        if (!scwin.eachDateCheck("[웹반영일]", med_ClmDtlWebDpDd)) {
            return false;
        }
    }
    if (!scwin.eachDateCheck("2. 기업심사위원회 심의대상여부 결정 및 결정일자", edt_REAL_INVSTG_OBJ_DECSN_DD)) {
        return false;
    }
    if (!scwin.eachDateCheck("3. 개선계획서 제출일", edt_IMPR_PLANDOC_SUBMIT_DD)) {
        return false;
    }
    if (!scwin.eachDateCheck("6. 이의신청서 제출일", edt_EINSPRUCH_SUBMIT_DD)) {
        return false;
    }
    if (!scwin.eachDateCheck("8. 정리매매기간 시작일", edt_ARRANTRD_STRT_DD)) {
        return false;
    }
    if (!scwin.eachDateCheck("8. 정리매매기간 종료일", edt_ARRANTRD_END_DD)) {
        return false;
    }
    if (edt_ARRANTRD_STRT_DD.getValue() != "" && edt_ARRANTRD_END_DD.getValue() != "") {
        if (!$c.stf.compareFromToDate(edt_ARRANTRD_STRT_DD, edt_ARRANTRD_END_DD, "정리매매기간 시작일", "정리매매기간 종료일")) {
            return false;
        }
    }
    if (!scwin.eachDateCheck("9. 상장폐지일", edt_DELIST_DD)) {
        return false;
    }
    return true;
};
scwin.eachDateCheck = function(comment, dateComponent) {
    if (dateComponent.getText() != "") {
        if (!scwin.checkDate(dateComponent.getText())) {
            $c.win.alert(comment + " 날짜형식을 확인하세요");
            dateComponent.focus();
            return false;
        }
    }
    return true;
};


/**
 *	저장, 수정시 사유(결과,결과(직접)) 입력여부 확인
 */
scwin.fn_checkRsnVal = function() {
    if (dts_Dtl1.getTotalRow() == 0) {
        $c.win.alert("실질심사 사유 및 사유발생일을 입력하세요.");
        return false;
    }
    var occrDd, imprDd = "";
    var isOkDate = true;
    for (j = 1; j <= dts_Dtl1.getTotalRow(); j++) {
        if (dts_Dtl1.getCellData(j, "LIST_ELIGTY_PROCS_RSN_VAL") == "") {
            $c.win.alert(j + "번째 [1. 실질심사 사유 및 사유발생일 '사유']를 입력하세요.");
            dtl_Grd1.SetColumn("LIST_ELIGTY_PROCS_RSN_VAL");
            dtl_Grd1.focus();
            return false;
        }
        if (dts_Dtl1.getCellData(j, "OCCR_DD") == "") {
            $c.win.alert(j + "번째 [1. 실질심사 사유 및 사유발생일 '일자']를 입력하세요.");
            dtl_Grd1.SetColumn("OCCR_DD");
            dtl_Grd1.focus();
            return false;
        }
        occrDd = dts_Dtl1.getCellData(j, "OCCR_DD");
        isOkDate = scwin.checkDate(occrDd);
        if (!isOkDate) {
            $c.win.alert(j + "번째 [1. 실질심사 사유 및 사유발생일 '일자'] 형식을 확인하세요.");
            return false;
        }
    }
    for (j = 1; j <= dts_Dtl2.getTotalRow(); j++) {
        if (dts_Dtl2.getCellData(j, "LIST_ELIGTY_PROCS_RSN_VAL") == "" && dts_Dtl2.getCellData(j, "LIST_ELIGTY_PROCS_RSN_CONTN") == "") {
            $c.win.alert(j + "번째 [4. 기업심사위원회 심의 결과 및 결정일자 '결과']를 입력하세요.");
            dtl_Grd2.SetColumn("LIST_ELIGTY_PROCS_RSN_VAL");
            dtl_Grd2.focus();
            return false;
        }
        if (dts_Dtl2.getCellData(j, "OCCR_DD") == "") {
            $c.win.alert(j + "번째 [4. 기업심사위원회 심의 결과 및 결정일자 '일자']를 입력하세요.");
            dtl_Grd2.SetColumn("OCCR_DD");
            dtl_Grd2.focus();
            return false;
        }
        occrDd = dts_Dtl2.getCellData(j, "OCCR_DD");
        isOkDate = scwin.checkDate(occrDd);
        if (!isOkDate) {
            $c.win.alert(j + "번째 [4. 기업심사위원회 심의 결과 및 결정일자 '일자'] 형식을 확인하세요.");
            return false;
        }
        imprDd = dts_Dtl2.getCellData(j, "IMPR_DEADLINE_DD");
        isOkDate = scwin.checkDate(imprDd);
        if (!isOkDate) {
            $c.win.alert(j + "번째 [4. 기업심사위원회 심의 결과 및 결정일자 '개선기한'] 형식을 확인하세요.");
            return false;
        }
    }
    for (j = 1; j <= dts_Dtl3.getTotalRow(); j++) {
        var text = "5. 이의신청 前 코스닥시장위원회 심의·의결 결과 및 결정일자";
        if (scwin.market == "1") {
            text.setValue("5. 기업심사위원회(개선기간 종료) 심의·의결 결과 및 결정일자");
        }
        if (dts_Dtl3.getCellData(j, "LIST_ELIGTY_PROCS_RSN_VAL") == "" && dts_Dtl3.getCellData(j, "LIST_ELIGTY_PROCS_RSN_CONTN") == "") {
            $c.win.alert(j + "번째 [" + text + " '결과']를 입력하세요.");
            dtl_Grd3.SetColumn("LIST_ELIGTY_PROCS_RSN_VAL");
            dtl_Grd3.focus();
            return false;
        }
        if (dts_Dtl3.getCellData(j, "OCCR_DD") == "") {
            $c.win.alert(j + "번째 [" + text + " ' 일자']를 입력하세요.");
            dtl_Grd3.SetColumn("OCCR_DD");
            dtl_Grd3.focus();
            return false;
        }
        occrDd = dts_Dtl3.getCellData(j, "OCCR_DD");
        isOkDate = scwin.checkDate(occrDd);
        if (!isOkDate) {
            $c.win.alert(j + "번째 [" + text + " '일자'] 형식을 확인하세요.");
            return false;
        }
        imprDd = dts_Dtl3.getCellData(j, "IMPR_DEADLINE_DD");
        isOkDate = scwin.checkDate(imprDd);
        if (!isOkDate) {
            $c.win.alert(j + "번째 [" + text + " '개선기한'] 형식을 확인하세요.");
            return false;
        }
    }
    for (j = 1; j <= dts_Dtl4.getTotalRow(); j++) {
        var text = "7. 이의신청 後 코스닥시장위원회 심의·의결 결과 및 결정일자";
        if (scwin.market == "1") {
            text.setValue("7. 상장공시위원회 심의·의결 결과 및 결정일자");
        }
        if (dts_Dtl4.getCellData(j, "LIST_ELIGTY_PROCS_RSN_VAL") == "" && dts_Dtl4.getCellData(j, "LIST_ELIGTY_PROCS_RSN_CONTN") == "") {
            $c.win.alert(j + "번째 [" + text + " '결과']를 입력하세요.");
            dtl_Grd4.SetColumn("LIST_ELIGTY_PROCS_RSN_VAL");
            dtl_Grd4.focus();
            return false;
        }
        if (dts_Dtl4.getCellData(j, "OCCR_DD") == "") {
            $c.win.alert(j + "번째 [" + text + " '일자']를 입력하세요.");
            dtl_Grd4.SetColumn("OCCR_DD");
            dtl_Grd4.focus();
            return false;
        }
        occrDd = dts_Dtl4.getCellData(j, "OCCR_DD");
        isOkDate = scwin.checkDate(occrDd);
        if (!isOkDate) {
            $c.win.alert(j + "번째 [" + text + " '일자'] 형식을 확인하세요.");
            return false;
        }
        imprDd = dts_Dtl4.getCellData(j, "IMPR_DEADLINE_DD");
        isOkDate = scwin.checkDate(imprDd);
        if (!isOkDate) {
            $c.win.alert(j + "번째 [" + text + " '개선기한'] 형식을 확인하세요.");
            return false;
        }
    }
    for (j = 1; j <= dts_Dtl5.getTotalRow(); j++) {
        var text = "10. 상장폐지 관련소송 결과 및 선고일자";
        if (dts_Dtl5.getCellData(j, "LIST_ELIGTY_PROCS_RSN_VAL") == "" && dts_Dtl5.getCellData(j, "LIST_ELIGTY_PROCS_RSN_CONTN") == "") {
            $c.win.alert(j + "번째 [" + text + " '결과']를 입력하세요.");
            dtl_Grd5.SetColumn("LIST_ELIGTY_PROCS_RSN_VAL");
            dtl_Grd5.focus();
            return false;
        }
        if (dts_Dtl5.getCellData(j, "OCCR_DD") == "") {
            $c.win.alert(j + "번째 [" + text + " '선고일자']를 입력하세요.");
            dtl_Grd5.SetColumn("OCCR_DD");
            dtl_Grd5.focus();
            return false;
        }
        occrDd = dts_Dtl5.getCellData(j, "OCCR_DD");
        isOkDate = scwin.checkDate(occrDd);
        if (!isOkDate) {
            $c.win.alert(j + "번째 [" + text + " '선고일자'] 형식을 확인하세요.");
            return false;
        }
    }
    return true;
};
scwin.fn_save = function() {
    if (!scwin.fn_CheckForm()) return;
    if (!scwin.fn_checkRsnVal()) return;
    scwin.trsIdx = TRS_IDX_INSERT;
    if (!$c.lc.fn_isProcess('I')) return;
    scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
    if (scwin.vBzProcsNo.length != 14) {
        $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
    } else {
        dts_Mst.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        dts_Mst.setCellData(1, "ISUR_CD", $c.stf.getObjectValue(txb_ISUR_CD));
        scwin.setBzProcsNo();
        scwin.fn_trs();
    }
};



/*
 *	신규 입력시 업무처리번호 셋팅
 */
scwin.setBzProcsNo = function(bzProcsNo) {
    var dtl1Row = dts_Dtl1.getTotalRow();
    for (k = 1; k <= dts_Dtl1.getTotalRow(); k++) {
        dts_Dtl1.setCellData(k, "BZ_PROCS_NO", scwin.vBzProcsNo);
    }
    for (k = 1; k <= dts_Dtl2.getTotalRow(); k++) {
        dts_Dtl2.setCellData(k, "BZ_PROCS_NO", scwin.vBzProcsNo);
    }
    for (k = 1; k <= dts_Dtl3.getTotalRow(); k++) {
        dts_Dtl3.setCellData(k, "BZ_PROCS_NO", scwin.vBzProcsNo);
    }
    for (k = 1; k <= dts_Dtl4.getTotalRow(); k++) {
        dts_Dtl4.setCellData(k, "BZ_PROCS_NO", scwin.vBzProcsNo);
    }
    for (k = 1; k <= dts_Dtl5.getTotalRow(); k++) {
        dts_Dtl5.setCellData(k, "BZ_PROCS_NO", scwin.vBzProcsNo);
    }
};
scwin.fn_update = function() {
    scwin.trsIdx = TRS_IDX_UPDATE;
    if (!scwin.fn_CheckForm()) return;
    if (!scwin.fn_checkRsnVal()) return;
    if (!$c.lc.fn_isProcess('U')) return;
    scwin.selRow = dts_List.getRowPosition();
    scwin.fn_trs();
};
scwin.fn_delete = function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    scwin.fn_trs();
};
scwin.fn_trs = function() {
    var vScrenProcTpCd;
    if (scwin.trsIdx == TRS_IDX_INSERT) {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (scwin.trsIdx == TRS_IDX_UPDATE) {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (scwin.trsIdx == TRS_IDX_DELETE) {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "REG_EMP_NO", js_id);
