scwin.fn_grdFileDownload = function(row, colid) {
    var bzProcsNo = dts_Dtl5.getCellData(row, "BZ_PROCS_NO");
    var pkString = "";
    if (colid == "ATTACH_FILE_NM1") {
        pkString = dts_Dtl5.getCellData(row, "ATTACH_FILE_NM1_PK");
    } else {
        pkString = dts_Dtl5.getCellData(row, "ATTACH_FILE_NM2_PK");
    }
    var procsNo = pkString.split("_")[0];
    var dtlSeq = pkString.split("_")[1];
    var fileSeq = pkString.split("_")[2];
    location.href = "/filedownload.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08 + "&BZ_PROCS_NO=" + bzProcsNo + "&LIST_ELIGTY_PROCS_CD=" + procsNo + "&LIST_ELIGTY_INVSTG_DTL_SEQ=" + dtlSeq + "&ATTACH_FILE_SEQ=" + fileSeq + "&gubun=42";
