        scwin.callElasticFileNoti("DELETE");
    }
    var status = buttonSet.status;
    $c.lc.fn_alertMsg('S');
    scwin.fn_list_sync();
    if (status == "U") {
        dts_List.setRowPosition(scwin.selRow, 0);
        scwin.fn_OpenDetail(scwin.selRow);
