    return true;
};
scwin.dtl_Grd4_CanColumnPosChange = function(row, colid) {
    return true;
};
scwin.trs_File_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "첨부파일삭제"));
    scwin.callElasticFileNoti("POST");
};
scwin.trs_File_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "첨부파일삭제"));
};
scwin.image_5_onclick = function() {
    scwin.fn_addRow(dts_Dtl5, dtl_Grd5, "E");
};
scwin.image_6_onclick = function() {
    scwin.fn_deleteRow(dts_Dtl5, dtl_Grd5);
};
scwin.dtl_Grd5_OnPopup = function(row, colid, data) {
    if (colid == "ATTACH_FILE_NM1") {
        scwin.fn_AttachFile(dts_Dtl5, row, "C");
    } else if (colid == "ATTACH_FILE_NM2") {
        scwin.fn_AttachFile(dts_Dtl5, row, "D");
    }
};
scwin.dtl_Grd5_OnDblClick = function(row, colid) {
    if (colid == "ATTACH_FILE_NM1" || colid == "ATTACH_FILE_NM2") {
        var fileNm = dts_Dtl5.getCellData(row, colid);
        if (fileNm != "") {
            scwin.fn_grdFileDownload(row, colid);
        }
    }
};
